package com.jiugeng.erp.product;
import static com.jiugeng.erp.product.ProductTypes.*;import com.jiugeng.erp.iam.AuthenticatedActor;import com.jiugeng.erp.iam.AuditHistoryLookup;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.List;import org.springframework.context.annotation.Profile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @Profile("!mock") @RequestMapping("/api/v1/products") class ProductController{private final ProductService service;private final ProductPageService pages;private final ProductCustomsService customs;private final ProductNameStyleService nameStyle;private final ProductSkuExportService exports;private final AuditHistoryLookup history;ProductController(ProductService service,ProductPageService pages,ProductSkuExportService exports,AuditHistoryLookup history,ProductCustomsService customs,ProductNameStyleService nameStyle){this.pages=pages;this.nameStyle=nameStyle;this.customs=customs;this.service=service;this.exports=exports;this.history=history;}
@GetMapping @PreAuthorize("hasAuthority('products.read')") List<ProductView> products(Authentication a){return service.products(has(a,"suppliers.read"));}
@GetMapping("/skus") @PreAuthorize("hasAuthority('products.read')") SkuPage skus(@RequestParam(required=false)String productId,@RequestParam(defaultValue="")String field,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="true")boolean exact,@RequestParam(required=false)VariantStatus status,@RequestParam(required=false)ProductStatus productStatus,@RequestParam(required=false)String productType,@RequestParam(required=false)Boolean hasImage,@RequestParam(required=false)Boolean hasSupplier,@RequestParam(required=false)Boolean hasMaterial,@RequestParam(defaultValue="updatedAt")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size,Authentication a){return service.skus(field,q,exact,status,productStatus,productType,hasImage,hasSupplier,hasMaterial,sort,direction,page,size,has(a,"suppliers.read"),productId);}
@org.springframework.transaction.annotation.Transactional(readOnly=true)
@GetMapping("/skus/export") @PreAuthorize("hasAuthority('products.export')") org.springframework.http.ResponseEntity<byte[]> exportSkus(@RequestParam(defaultValue="")String field,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="true")boolean exact,@RequestParam(required=false)VariantStatus status,@RequestParam(required=false)ProductStatus productStatus,@RequestParam(required=false)String productType,@RequestParam(required=false)Boolean hasImage,@RequestParam(required=false)Boolean hasSupplier,@RequestParam(required=false)Boolean hasMaterial,@RequestParam(required=false)List<String>variantIds,@RequestParam(defaultValue="updatedAt")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="")String stock,@RequestParam(defaultValue="")String missing,Authentication a){
 if(!has(a,"suppliers.read")&&(hasSupplier!=null||"supplier".equals(missing)))throw new ProductException(403,"FILTER_FORBIDDEN","无供应商查看权限");
 if(!has(a,"inventory.read")&&!stock.isEmpty())throw new ProductException(403,"FILTER_FORBIDDEN","无库存查看权限");
 var filter=new ProductPageService.Filter(q,field,exact,productStatus==null?"":productStatus.name(),status==null?"":status.name(),hasImage==null?"":hasImage.toString(),hasSupplier==null?"":hasSupplier.toString(),hasMaterial==null?"":hasMaterial.toString(),stock,missing,productType,variantIds);
 var first=pages.page(filter,sort,direction,0,100,has(a,"suppliers.read"),false);
 if(first.matchingSkuCount()>10000)throw new ProductException(400,"SKU_EXPORT_LIMIT_EXCEEDED","导出最多 10000 条，请缩小筛选范围");
 var rows=new java.util.ArrayList<SkuListItem>();
 for(int index=0;index==0||index*100L<first.totalCount();index++){
  var current=index==0?first:pages.page(filter,sort,direction,index,100,has(a,"suppliers.read"),false);
  var matches=new java.util.HashSet<>(current.matchingVariantIds());
  for(var product:current.items())for(var variant:product.variants())if(matches.contains(variant.id()))rows.add(new SkuListItem(product.id(),product.productCode(),product.productName(),product.status(),product.productType(),variant,product.status()==ProductStatus.ACTIVE&&variant.status()==VariantStatus.ACTIVE,product.updatedAt()));
 }
 byte[] content=exports.export(rows);return org.springframework.http.ResponseEntity.ok().contentType(org.springframework.http.MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).header(org.springframework.http.HttpHeaders.CONTENT_DISPOSITION,org.springframework.http.ContentDisposition.attachment().filename("product-skus.xlsx").build().toString()).body(content);
}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('products.read')") ProductView product(@PathVariable String id,Authentication a){return service.product(id,has(a,"suppliers.read"));}
@GetMapping("/{id}/history") @PreAuthorize("hasAuthority('products.read')") List<AuditHistoryLookup.HistoryEvent> history(@PathVariable String id){service.product(id,false);return history.find("PRODUCT",id);}
@org.springframework.transaction.annotation.Transactional @PostMapping @PreAuthorize("hasAuthority('products.write')") ProductView create(@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){ProductView saved=service.create(r.input(),actor,has(a,"suppliers.read"));saveVariantPresentation(saved,r,actor);return service.product(saved.id(),has(a,"suppliers.read"));}
@org.springframework.transaction.annotation.Transactional @PutMapping("/{id}") @PreAuthorize("hasAuthority('products.write')") ProductView update(@PathVariable String id,@Valid@RequestBody ProductRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){ProductView saved=service.update(id,r.input(),actor,has(a,"suppliers.read"));saveVariantPresentation(saved,r,actor);return service.product(id,has(a,"suppliers.read"));}
@org.springframework.transaction.annotation.Transactional @PutMapping("/{id}/skus/{variantId}") @PreAuthorize("hasAuthority('products.write')")
ProductView updateSku(@PathVariable String id,@PathVariable String variantId,@Valid@RequestBody VariantRequest request,@AuthenticationPrincipal AuthenticatedActor actor,Authentication auth){
 var saved=service.updateSku(id,variantId,request.input(),actor,has(auth,"suppliers.read"));
 if(request.customs()!=null)customs.save(variantId,request.customs(),actor);
 if(request.nameHighlighted()!=null||request.nameStyles()!=null)nameStyle.save(id,variantId,request.variantName(),request.nameHighlighted(),request.nameStyles(),actor);
 return service.product(saved.id(),has(auth,"suppliers.read"));
}
@GetMapping("/{id}/skus/{variantId}/history") @PreAuthorize("hasAuthority('products.read')")
List<AuditHistoryLookup.HistoryEvent> skuHistory(@PathVariable String id,@PathVariable String variantId){
 if(service.product(id,false).variants().stream().noneMatch(v->v.id().equals(variantId)))throw new ProductException(404,"SKU_NOT_FOUND","子体不存在");
 return history.find("PRODUCT_VARIANT",variantId);
}
@PostMapping("/{id}/disable") @PreAuthorize("hasAuthority('products.write')") ProductView disable(@PathVariable String id,@Valid@RequestBody VersionRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.disable(id,r.version(),actor,has(a,"suppliers.read"));}
@PostMapping("/skus/batch") @PreAuthorize("hasAuthority('products.write')") List<ProductView> batch(@Valid@RequestBody BatchRequest r,@AuthenticationPrincipal AuthenticatedActor actor,Authentication a){return service.batch(r.items().stream().map(BatchItem::input).toList(),actor,has(a,"suppliers.read"));}
private void saveVariantPresentation(ProductView saved,ProductRequest request,AuthenticatedActor actor){for(var input:request.variants()){if(input.customs()==null && input.nameHighlighted()==null && input.nameStyles()==null)continue;var sku=saved.variants().stream().filter(v->input.id()!=null&&!input.id().isBlank()?v.id().equals(input.id()):ProductRepository.normalize(v.skuCode()).equals(ProductRepository.normalize(input.skuCode()))).findFirst().orElseThrow();if(input.customs()!=null)customs.save(sku.id(),input.customs(),actor);if(input.nameHighlighted()!=null || input.nameStyles()!=null)nameStyle.save(saved.id(),sku.id(),input.variantName(),input.nameHighlighted(),input.nameStyles(),actor);}}
private boolean has(Authentication a,String authority){return a.getAuthorities().stream().anyMatch(v->v.getAuthority().equals(authority));}
record ProductRequest(@Size(max=64)String productCode,@Size(max=200)String productName,@Size(max=200)String nameZh,@Size(max=100)String productType,@Size(max=1000)String description,ProductStatus status,Long version,@NotEmpty@Size(max=100)List<@Valid VariantRequest>variants,@Size(max=36)String imageAssetId){ProductInput input(){String name=productName==null||productName.isBlank()?nameZh:productName;return new ProductInput(productCode,name,productType,description,status,version,variants.stream().map(VariantRequest::input).toList(),imageAssetId);}}
record VariantRequest(String id,@Size(max=64)String skuCode,@NotBlank@Size(max=200)String variantName,@Size(max=200)String itemDimensions,@Size(max=200)String packageDimensions,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemLengthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemWidthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal itemHeightCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageLengthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageWidthCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=6,fraction=3)BigDecimal packageHeightCm,@DecimalMin(value="0",inclusive=false)@Digits(integer=9,fraction=3)BigDecimal packageWeightGrams,VariantStatus status,@Size(max=36)String imageAssetId,@Size(max=500)String imageUrl,Long version,@Size(max=50)List<@Valid SupplierRequest>suppliers,@Size(max=100)List<@Valid MaterialRequest>materials,@Valid CustomsProfile customs,Boolean nameHighlighted,@Size(max=200)List<@NotNull @Valid NameStyleSpan> nameStyles){VariantRequest{if((id==null||id.isBlank())&&(skuCode==null||skuCode.isBlank()))skuCode="SYS-SKU-"+java.util.UUID.randomUUID();}VariantInput input(){return new VariantInput(id,skuCode,variantName,itemDimensions,packageDimensions,itemLengthCm,itemWidthCm,itemHeightCm,packageLengthCm,packageWidthCm,packageHeightCm,packageWeightGrams,status,imageAssetId,imageUrl,version,suppliers==null?List.of():suppliers.stream().map(SupplierRequest::input).toList(),materials==null?List.of():materials.stream().map(MaterialRequest::input).toList());}}
record SupplierRequest(@NotBlank@Size(max=36)String supplierId,@Size(max=500)String purchaseUrl,@Size(max=500)String remark,boolean primary){SupplierAssignment input(){return new SupplierAssignment(supplierId,purchaseUrl,remark,primary);}}
record MaterialRequest(@NotBlank@Size(max=36)String materialId,@NotNull@DecimalMin(value="0",inclusive=false)BigDecimal standardQuantity,@NotBlank@Size(max=32)String unit,@DecimalMin("0")@DecimalMax("1")BigDecimal lossRate,@Size(max=1000)String remark,Boolean enabled){MaterialAssignment input(){return new MaterialAssignment(materialId,standardQuantity,unit,lossRate,remark,enabled==null||enabled);}}
record VersionRequest(@Min(0)long version){}
record BatchRequest(@NotEmpty@Size(max=100)List<@Valid BatchItem>items){}
record BatchItem(@NotBlank String productId,@NotBlank String variantId,@Min(0)long productVersion,@Min(0)long variantVersion,VariantStatus status,boolean statusSelected,BigDecimal itemLengthCm,BigDecimal itemWidthCm,BigDecimal itemHeightCm,boolean itemDimensionsSelected,BigDecimal packageLengthCm,BigDecimal packageWidthCm,BigDecimal packageHeightCm,boolean packageDimensionsSelected,BigDecimal packageWeightGrams,boolean packageWeightSelected){BatchVariantPatch input(){return new BatchVariantPatch(productId,variantId,productVersion,variantVersion,status,statusSelected,itemLengthCm,itemWidthCm,itemHeightCm,itemDimensionsSelected,packageLengthCm,packageWidthCm,packageHeightCm,packageDimensionsSelected,packageWeightGrams,packageWeightSelected);}}
}
